import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomSwitch,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import transportApi from "../../../api/transport/transportApi";
import { Modal } from "antd";
import CustomTextArea from "../../../components/forms/CustomTextArea";

export default function SettlementAccountsFormModal({
  ismodalOpen,
  setisModalOpen,
  settlementAccount,
  modalTitle = "Add new settlement account",
  updated,
  setUpdated,
}) {
  const [saccoPersonnel, setsaccoPersonnel] = useState([]);
  const getSaccoPersonnelApi = useApi(transportApi.transportAction);
  const transportActionsApi = useApi(transportApi.transportAction);
  const getRoutes = async () => {
    await getSaccoPersonnelApi.request({
      action: "GetSaccoPersonnel",
    });
  };

  useEffect(() => {
    getRoutes();
  }, []);

  useEffect(() => {
    if (getSaccoPersonnelApi.data && getSaccoPersonnelApi.data.length) {
      setsaccoPersonnel(
        getSaccoPersonnelApi.data.map((i) => ({
          label: `${i.first_name} ${i.last_name} - ${i.phone}`,
          value: i.id,
        }))
      );
    }

    console.log("getRoutesActionsApi.data", getSaccoPersonnelApi.data);
  }, [getSaccoPersonnelApi.data]);

  const [errors, setErrors] = useState();

  const handleRouteAction = async (data) => {
    console.log("data at", data);
    const result = await transportActionsApi.request(data);

    if (result.ok) {
      console.log("res", result);
      setUpdated(true);
      setisModalOpen(false);
    } else {
      setUpdated(false);
    }
  };

  useEffect(() => {
    if (transportActionsApi.data) {
      setisModalOpen(false);
      // if (transportActionsApi.data.destination) {
      //     setDestination(transportActionsApi.data.destination)
      // }

      if (transportActionsApi.data.errors) {
        setErrors(transportActionsApi.data.errors);
      }
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      administrator: settlementAccount
        ? {
            label: settlementAccount.administrator_title,
            value: settlementAccount.administrator,
          }
        : "",
      account_name: settlementAccount ? settlementAccount.account_name : "",
      account_phone_number: settlementAccount
        ? settlementAccount.account_phone_number
        : "",
      is_active: settlementAccount ? settlementAccount.is_active : "",
      description: settlementAccount ? settlementAccount.description : "",
    },

    validationSchema: Yup.object({
      administrator: Yup.object().required("Administrator ID is required"),
      account_name: Yup.string()
        .min(3, "Must be 3 characters or more")
        .required("Account name is required"),
      account_phone_number: Yup.number()
        .min(0, "Must be 3 characters or more")
        .required("Account phone is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (settlementAccount) {
        handleRouteAction({
          action: "UpdateSaccoSettlementAccount",
          sacco_settlement_account_details: {
            sacco_settlement_account_id: settlementAccount.id,

            is_active: values.is_active,
            description: values.description ? values.description : "",
          },
        });
      } else {
        handleRouteAction({
          action: "CreateSaccoSettlementAccount",
          sacco_settlement_account_details: {
            administrator_id: values.administrator.value,
            account_phone_number: values.account_phone_number,
            account_name: values.account_name,
            description: values.description ? values.description : "",
          },
        });
      }

      // resetForm();
    },
  });

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  const [switchStatus, setswitchStatus] = useState(
    settlementAccount && settlementAccount.is_active === "true" ? true : false
  );
  const [switchLabel, setswitchLabel] = useState("Activate");
  const handleSwitchChange = (checked) => {
    console.log("Swict", checked);
    formik.setFieldValue("is_active", checked ? "true" : "false");
    setswitchLabel(checked ? "Deactivate" : "Activate");

    // console.log('eee', e.target.checked)
  };

  return (
    <div className="w-full">
      <Modal
        width={560}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.account_name}
            error={formik.errors.account_name}
          >
            <CustomInput
              required={true}
              id="account_name"
              name="account_name"
              onChange={formik.handleChange}
              placeholder="Enter account name"
              size="large"
              type="text"
              value={formik.values.account_name}
              label="Enter account name"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.account_phone_number}
            error={formik.errors.account_phone_number}
          >
            <CustomInput
              required={true}
              id="account_phone_number"
              name="account_phone_number"
              onChange={formik.handleChange}
              placeholder="Enter account phone number"
              size="large"
              type="text"
              value={formik.values.account_phone_number}
              label="Enter account phone number"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.administrator}
            error={formik.errors.administrator}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="administrator"
              id="administrator"
              label="Select account administrator"
              size="large"
              onChange={(value) => formik.setFieldValue("administrator", value)}
              value={formik.values.administrator}
              placeholder="Select account administrator"
              options={saccoPersonnel}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
          >
            <CustomTextArea
              required={true}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Enter short description of account"
              size="large"
              type="text"
              rows={2}
              value={formik.values.description}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.is_active}
            error={formik.errors.is_active}
          >
            <CustomSwitch
              id="is_active"
              checked={formik.values.is_active === "true"}
              onChange={(e) => handleSwitchChange(e)}
              title={switchLabel}
              label="Status"
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
